package com.rustraid.ui.screens
import androidx.compose.animation.core.*;import androidx.compose.foundation.background;import androidx.compose.foundation.gestures.detectTapGestures;import androidx.compose.foundation.layout.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.*;import androidx.compose.ui.input.pointer.pointerInput;import androidx.compose.ui.unit.dp;import androidx.compose.ui.unit.sp
@Composable fun AlarmScreen(onAcknowledge:()->Unit){var held by remember{mutableStateOf(false)};val scale by rememberInfiniteTransition(label="alarm").animateFloat(.9f,1.1f,infiniteRepeatable(tween(400),RepeatMode.Reverse),label="s");LaunchedEffect(held){if(held){kotlinx.coroutines.delay(1500);onAcknowledge()}};Column(Modifier.fillMaxSize().background(MaterialTheme.colorScheme.error).padding(24.dp),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Text("🚨",fontSize=(100*scale).sp);Text("YOU ARE BEING RAIDED",fontSize=30.sp);Text("Get up NOW");Spacer(Modifier.height(48.dp));Button(onClick={},modifier=Modifier.pointerInput(Unit){detectTapGestures(onPress={held=true;tryAwaitRelease();held=false})}){Text(if(held)"KEEP HOLDING…" else "HOLD TO ACKNOWLEDGE")}}}
